<template><div class="project-list-page"><div class="list-view-toolbar"><div class="list-title-block"><div><h1>图纸变更</h1><p class="list-caption">文控登记版本，重大变化按需提交技术审核</p></div><el-button type="primary" :icon="Upload" @click="ElMessage.info('图纸上传入口已预留')">上传新版本</el-button></div><div class="search-control"><el-icon><Search /></el-icon><el-input v-model="keyword" placeholder="搜索变更单、图纸或零件" clearable /></div><div class="filter-controls"><el-select v-model="status" placeholder="状态" clearable><el-option v-for="item in ['技术审核中','已生效','草稿']" :key="item" :label="item" :value="item" /></el-select></div></div><div class="table-meta"><span>{{ filtered.length }} 条图纸变更</span><span>是否更新PPAP默认：不需要</span></div><el-table :data="filtered" stripe><el-table-column prop="id" label="变更单" width="135" /><el-table-column prop="project" label="项目" width="130" /><el-table-column prop="part" label="关联零件" min-width="180" /><el-table-column label="图纸版本" width="145"><template #default="{ row }"><span class="mono">{{ row.drawing }} {{ row.from }} → {{ row.to }}</span></template></el-table-column><el-table-column prop="reason" label="变化说明" min-width="180" /><el-table-column prop="tech" label="技术审核" width="125"><template #default="{ row }"><el-tag size="small" :type="row.tech === '待技术审核' ? 'warning' : 'info'">{{ row.tech }}</el-tag></template></el-table-column><el-table-column prop="ppap" label="PPAP" width="90" /><el-table-column prop="effective" label="生效日期" width="120" /><el-table-column prop="status" label="状态" width="115"><template #default="{ row }"><el-tag size="small" :type="row.status === '已生效' ? 'success' : 'warning'">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{ row }"><el-button v-if="row.status === '技术审核中'" link type="primary" @click="ElMessage.success('已打开技术审核')">技术审核</el-button><el-button link type="primary" @click="ElMessage.success(`${row.id} 详情已打开`)">查看</el-button></template></el-table-column></el-table></div></template>
<script setup lang="ts">
import { computed, ref } from 'vue'
import { Search, Upload } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import { changes } from './data'
const keyword = ref(''); const status = ref(''); const filtered = computed(() => changes.filter(row => { const text = `${row.id} ${row.project} ${row.part} ${row.drawing} ${row.reason}`.toLowerCase(); return (!keyword.value || text.includes(keyword.value.toLowerCase())) && (!status.value || row.status === status.value) }))
</script>
<style scoped>.project-list-page{min-width:0;padding:18px 0 30px;color:var(--zephyr-ink)}.project-list-page h1{margin:0;color:var(--zephyr-ink);font-size:19px}.list-caption{margin:5px 0 0;color:var(--zephyr-muted);font-size:11px}.mono{font-family:'IBM Plex Mono',Consolas,monospace;font-size:10px}</style>
